#[test]
fn a_base_that_does_not_match_its_manifest_is_skipped_and_one_that_is_gone_fails() {
    let f = Fixture::standard();
    let origin = Origin::start(&f.origin);
    let config = f.fetch_config(&origin.feed_url(), "");
    let pack = format!("2.0.0/{}.pack", target());
    let mut bytes = fs::read(f.origin.join(&pack)).unwrap();
    let last = bytes.len() - 1;
    bytes[last] ^= 1;
    origin.body(&pack, bytes);
    let dir = f.out_dir("skipped");
    let out = f.fetch(&config, &dir, "2.0.1", &[]);
    assert_ok(&out, "a corrupted base pack");
    assert!(
        stdout(&out).contains(&format!("base: 2.0.0 {} skipped:", target())),
        "{}",
        stdout(&out)
    );
    assert_eq!(versions(&dir), ["1.10.0", "2.0.0-rc.1"]);
    assert_eq!(lines_of(&out), origin.log());

    // A shorter body.
    let mut short = fs::read(f.origin.join(&pack)).unwrap();
    short.truncate(short.len() - 5);
    origin.body(&pack, short);
    let dir = f.out_dir("short");
    assert_ok(&f.fetch(&config, &dir, "2.0.1", &[]), "a short base pack");
    assert_eq!(versions(&dir), ["1.10.0", "2.0.0-rc.1"]);

    // A listed manifest or pack that the server no longer has is not a skip.
    let origin2 = Origin::start(&f.origin);
    origin2.status(&format!("2.0.0/{}.manifest.json", target()), 404);
    let config2 = f.fetch_config(&origin2.feed_url(), "");
    let dir = f.out_dir("gone");
    let err = assert_fails(
        &f.fetch(&config2, &dir, "2.0.1", &[]),
        1,
        "a missing manifest",
    );
    assert!(err.contains("the server answered 404"), "{err}");
    assert!(!dir.exists());
    let origin3 = Origin::start(&f.origin);
    origin3.status(&pack, 500);
    let config3 = f.fetch_config(&origin3.feed_url(), "");
    let err = assert_fails(
        &f.fetch(&config3, &f.out_dir("gone2"), "2.0.1", &[]),
        1,
        "a pack 500",
    );
    assert!(err.contains("the server answered 500"), "{err}");
}

#[test]
fn no_secret_is_read() {
    let f = Fixture::standard();
    let origin = Origin::start(&f.origin);
    let config = f.fetch_config(&origin.feed_url(), "");
    // Values made now, never committed.
    let unique = |label: &str| {
        let mut hasher = std::collections::hash_map::RandomState::new().build_hasher();
        hasher.write_u64(u64::from(std::process::id()));
        format!("{label}-{:016x}", hasher.finish())
    };
    let (key, secret, account) = (unique("access"), unique("secret"), unique("account"));
    let (key, secret, account) = (key.as_str(), secret.as_str(), account.as_str());
    let env = [
        ("HELLO_R2_KEY", key),
        ("HELLO_R2_SECRET", secret),
        ("HELLO_R2_ACCOUNT_ID", account),
    ];
    // With the variables set, nothing of them is shown; unset, the fetch is the same.
    let with = f.fetch(&config, &f.out_dir("with"), "2.0.1", &env);
    assert_ok(&with, "fetch with the variables set");
    for needle in [key, secret, account] {
        assert!(!stdout(&with).contains(needle) && !stderr(&with).contains(needle));
    }
    let without = f.fetch(&config, &f.out_dir("without"), "2.0.1", &[]);
    assert_ok(&without, "fetch without the variables");
    assert_eq!(
        names(&f.out_dir("with")),
        names(&f.out_dir("without")),
        "the variables change nothing"
    );
    // The instrument fires on text that does hold them.
    let leaky = Output {
        status: with.status,
        stdout: format!("using {secret}").into_bytes(),
        stderr: Vec::new(),
    };
    assert!(std::panic::catch_unwind(|| assert_no_secrets(&leaky, &[secret.as_bytes()])).is_err());
}

